 40	    private static void testWrapAroundBehavior() {
 41	        CircularQueue<Integer> queue = new CircularQueue<>(3);
 42	        queue.enqueue(1);
 43	        queue.enqueue(2);
 44	        queue.enqueue(3);
 45	        queue.dequeue();
 46	        queue.enqueue(4);
 47	
 48	        assertEquals("[2, 3, 4]", queue.toString(), "wrap-around should preserve iteration order");
 49	        assertEquals(Integer.valueOf(2), queue.peekFront(), "front should advance after dequeue");
 50	        assertEquals(Integer.valueOf(4), queue.peekRear(), "rear should track wrapped insertion");
 51	    }
